/**
 * FreeWire Phase 5 - AI 노드 자동 생성기
 *
 * 텍스트 한 줄 → 노드 그래프 JSON 자동 생성
 *
 * 동작 방식:
 *   1. IntentParser: 자연어 → 의도 파악 (키워드 + 패턴)
 *   2. TemplateEngine: 의도 → 노드 배치 계획
 *   3. LayoutEngine: 노드 위치 자동 계산 (겹침 방지)
 *   4. (선택) LLM 브릿지: 로컬 서버 or Claude API 연동
 */

'use strict';

