/**
 * FreeWire - component 노드 정의
 * freelang-light의 markup/style/props 블록과 직접 연결
 */

const { PORT_TYPES } = require('../node-spec');

/** 지원하는 컴포넌트 서브타입 */
const COMPONENT_TYPES = {
  BUTTON:    'button',
  INPUT:     'input',
  CARD:      'card',
  TEXT:      'text',
  LIST:      'list',
  CONTAINER: 'container',
  IMAGE:     'image',
};

/** 서브타입별 기본 props */
const DEFAULT_PROPS = {
  button: {
    label:    '클릭',
    variant:  'primary',   // primary | secondary | ghost
    disabled: false,
    onClick:  null,        // 연결된 logic 노드 id
  },
  input: {
    placeholder: '입력하세요',
    type:        'text',   // text | number | email | password
    value:       null,     // 연결된 data 노드 id
    onChange:    null,
  },
  card: {
    title:   '카드 제목',
    content: '내용을 입력하세요',
    variant: 'default',    // default | glass | elevated
  },
  text: {
    content: '텍스트',
    tag:     'p',          // p | h1 | h2 | h3 | span | label
    color:   '#000000',
  },
  list: {
    items:     null,       // 연결된 data 노드 id (배열)
    itemNode:  null,       // 반복 렌더링할 component 노드 id
    direction: 'vertical', // vertical | horizontal
  },
  container: {
    direction: 'column',   // column | row
    gap:       '8px',
    padding:   '16px',
    children:  [],         // 연결된 component 노드 id 목록
  },
  image: {
    src: '',
    alt: '이미지',
    width:  '100%',
    height: 'auto',
  },
};

/**
 * component 노드 생성
 * @param {string} id
 * @param {string} componentType - COMPONENT_TYPES 중 하나
 * @param {object} propsOverride - 기본 props 덮어쓰기
 * @returns {object} 노드 JSON
 */
function createComponentNode(id, componentType = 'button', propsOverride = {}) {
  const base = DEFAULT_PROPS[componentType] || {};

  return {
    id,
    type:          'component',
    componentType,
    inputs: [
      { portId: 'data',  label: '데이터',  portType: PORT_TYPES.DATA,  required: false },
      { portId: 'style', label: '스타일',  portType: PORT_TYPES.ANY,   required: false },
    ],
    outputs: [
      { portId: 'out',        label: '컴포넌트',  portType: PORT_TYPES.COMPONENT },
      { portId: 'clickEvent', label: '클릭 이벤트', portType: PORT_TYPES.LOGIC },
    ],
    props: { ...base, ...propsOverride },
    meta: {
      freelangBlock: 'markup',   // freelang-light 컴파일 대상
      position: { x: 0, y: 0 }, // 에디터 캔버스 좌표
    },
  };
}

/**
 * component 노드 → freelang-light markup 블록 문자열 변환
 * @param {object} node
 * @returns {string}
 */
function toFreelangMarkup(node) {
  const { componentType, props } = node;

  switch (componentType) {
    case 'button':
      return [
        `markup {`,
        `  <button class="${escapeAttr(props.variant)}"${props.disabled ? ' disabled' : ''}>`,
        `    ${escapeHtml(props.label)}`,
        `  </button>`,
        `}`,
      ].join('\n');

    case 'input':
      return [
        `markup {`,
        `  <input type="${escapeAttr(props.type)}" placeholder="${escapeAttr(props.placeholder)}" />`,
        `}`,
      ].join('\n');

    case 'card':
      return [
        `markup {`,
        `  <div class="card ${escapeAttr(props.variant)}">`,
        `    <h3>${escapeHtml(props.title)}</h3>`,
        `    <p>${escapeHtml(props.content)}</p>`,
        `  </div>`,
        `}`,
      ].join('\n');

    case 'text':
      return [
        `markup {`,
        `  <${escapeAttr(props.tag)} style="color: ${escapeAttr(props.color)}">${escapeHtml(props.content)}</${escapeAttr(props.tag)}>`,
        `}`,
      ].join('\n');

    case 'container':
      return [
        `markup {`,
        `  <div class="container" style="display:flex; flex-direction:${escapeAttr(props.direction)}; gap:${escapeAttr(props.gap)}; padding:${escapeAttr(props.padding)}">`,
        `    <!-- children -->`,
        `  </div>`,
        `}`,
      ].join('\n');

    default:
      return `markup { <div class="${escapeAttr(componentType)}"></div> }`;
  }
}

/**
 * HTML 속성값 이스케이프 (XSS 방지)
 * @param {*} val
 * @returns {string}
 */
function escapeAttr(val) {
  return String(val ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * HTML 텍스트 콘텐츠 이스케이프 (XSS 방지)
 * @param {*} val
 * @returns {string}
 */
function escapeHtml(val) {
  return String(val ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

module.exports = { COMPONENT_TYPES, DEFAULT_PROPS, createComponentNode, toFreelangMarkup, escapeAttr, escapeHtml };

