/**
 * FreeWire - data 노드 정의
 * 상수, 변수, 배열, 객체, API 응답 등 값 공급 노드
 */

const { PORT_TYPES } = require('../node-spec');

const DATA_TYPES = {
  STRING:  'string',
  NUMBER:  'number',
  BOOLEAN: 'boolean',
  ARRAY:   'array',
  OBJECT:  'object',
  STATE:   'state',    // 반응형 상태 (GlobalStateManager)
  PROPS:   'props',    // 외부 입력 props
};

/**
 * data 노드 생성
 * @param {string} id
 * @param {string} dataType - DATA_TYPES 중 하나
 * @param {*}      value    - 초기값
 * @param {object} opts     - { name, label }
 */
function createDataNode(id, dataType = 'string', value = '', opts = {}) {
  const label = opts.label || DATA_TYPE_LABELS[dataType] || '데이터';

  return {
    id,
    type:     'data',
    dataType,
    inputs:   dataType === 'state' || dataType === 'props'
      ? [{ portId: 'initial', label: '초기값', portType: PORT_TYPES.DATA, required: false }]
      : [],
    outputs: [
      { portId: 'value', label: '값', portType: PORT_TYPES.DATA },
      ...(dataType === 'state'
        ? [{ portId: 'setter', label: '변경 함수', portType: PORT_TYPES.LOGIC }]
        : []),
    ],
    props: {
      name:  opts.name || id,
      label,
      value,
      ...(dataType === 'state'  ? { reactive: true }  : {}),
      ...(dataType === 'props'  ? { required: false, defaultValue: value } : {}),
      ...(dataType === 'array'  ? { itemType: 'any' } : {}),
      ...(dataType === 'object' ? { schema: {} }      : {}),
    },
    meta: {
      freelangBlock: dataType === 'props' ? 'props' : 'script',
      position: { x: 0, y: 0 },
    },
  };
}

const DATA_TYPE_LABELS = {
  string:  '문자열',
  number:  '숫자',
  boolean: '참/거짓',
  array:   '배열',
  object:  '객체',
  state:   '상태(State)',
  props:   '프롭스(Props)',
};

/**
 * data 노드 → freelang-light 코드 변환
 * @param {object} node
 * @returns {string}
 */
function toFreelangCode(node) {
  const { dataType, props } = node;
  const val  = JSON.stringify(props.value);
  const name = safeName(props.name);

  switch (dataType) {
    case 'state':
      return [
        `script {`,
        `  let ${name} = ${val};`,
        `  function set_${name}(v) { ${name} = v; }`,
        `}`,
      ].join('\n');

    case 'props':
      return [
        `props {`,
        `  ${name}: ${dataType} = ${val};`,
        `}`,
      ].join('\n');

    case 'array':
      return `script { let ${name} = ${val}; }`;

    case 'object':
      return `script { let ${name} = ${val}; }`;

    default:
      return `script { let ${name} = ${val}; }`;
  }
}

/**
 * 값 타입 자동 추론 (리터럴 입력 시)
 * @param {*} value
 * @returns {string} DATA_TYPES 중 하나
 */
function inferType(value) {
  if (Array.isArray(value))       return DATA_TYPES.ARRAY;
  if (value === null)             return DATA_TYPES.STRING;
  switch (typeof value) {
    case 'string':  return DATA_TYPES.STRING;
    case 'number':  return DATA_TYPES.NUMBER;
    case 'boolean': return DATA_TYPES.BOOLEAN;
    case 'object':  return DATA_TYPES.OBJECT;
    default:        return DATA_TYPES.STRING;
  }
}

/**
 * FreeLang 식별자 검증 (코드 인젝션 방지)
 * @param {string} name
 * @returns {string} 안전한 식별자 (영숫자+언더스코어만)
 */
function safeName(name) {
  return String(name ?? 'var').replace(/[^\w]/g, '_');
}

module.exports = { DATA_TYPES, DATA_TYPE_LABELS, createDataNode, toFreelangCode, inferType, safeName };

/**
 * FreeWire - logic 노드 정의
 * if / loop / function / transform (map/filter/reduce)
 */

const { PORT_TYPES } = require('../node-spec');

const LOGIC_TYPES = {
  IF:        'if',
  LOOP:      'loop',
  FUNCTION:  'function',
  MAP:       'map',
  FILTER:    'filter',
  REDUCE:    'reduce',
};

/**
 * logic 노드 생성
 * @param {string} id
 * @param {string} logicType - LOGIC_TYPES 중 하나
 * @param {object} opts
 */
function createLogicNode(id, logicType = 'if', opts = {}) {
  const def = NODE_DEFS[logicType];
  if (!def) throw new Error(`알 수 없는 logicType: ${logicType}`);

  return {
    id,
    type:      'logic',
    logicType,
    inputs:    def.inputs,
    outputs:   def.outputs,
    props:     { ...def.defaultProps, ...opts },
    meta: {
      freelangBlock: 'script',
      position: { x: 0, y: 0 },
    },
  };
}

/** 로직 타입별 포트 & 기본 props 정의 */
const NODE_DEFS = {
  if: {
    inputs: [
      { portId: 'condition', label: '조건',       portType: PORT_TYPES.DATA,  required: true },
      { portId: 'then',      label: 'true일 때',  portType: PORT_TYPES.ANY,   required: true },
      { portId: 'else',      label: 'false일 때', portType: PORT_TYPES.ANY,   required: false },
    ],
    outputs: [
      { portId: 'out', label: '결과', portType: PORT_TYPES.ANY },
    ],
    defaultProps: { condition: '' },
  },

  loop: {
    inputs: [
      { portId: 'items',    label: '배열',    portType: PORT_TYPES.DATA,      required: true },
      { portId: 'template', label: '템플릿',  portType: PORT_TYPES.COMPONENT, required: true },
    ],
    outputs: [
      { portId: 'out', label: '렌더 목록', portType: PORT_TYPES.COMPONENT },
    ],
    defaultProps: { itemName: 'item', indexName: 'i' },
  },

  function: {
    inputs: [
      { portId: 'args', label: '인자', portType: PORT_TYPES.DATA, required: false },
    ],
    outputs: [
      { portId: 'result', label: '반환값', portType: PORT_TYPES.DATA },
    ],
    defaultProps: { name: 'myFunc', body: 'return args;', params: [] },
  },

  map: {
    inputs: [
      { portId: 'array',    label: '배열',    portType: PORT_TYPES.DATA,  required: true },
      { portId: 'transform',label: '변환식',  portType: PORT_TYPES.LOGIC, required: true },
    ],
    outputs: [
      { portId: 'out', label: '변환된 배열', portType: PORT_TYPES.DATA },
    ],
    defaultProps: { itemName: 'item', expression: 'item' },
  },

  filter: {
    inputs: [
      { portId: 'array',     label: '배열',  portType: PORT_TYPES.DATA,  required: true },
      { portId: 'condition', label: '조건',  portType: PORT_TYPES.LOGIC, required: true },
    ],
    outputs: [
      { portId: 'out', label: '필터된 배열', portType: PORT_TYPES.DATA },
    ],
    defaultProps: { itemName: 'item', condition: 'item != null' },
  },

  reduce: {
    inputs: [
      { portId: 'array',   label: '배열',    portType: PORT_TYPES.DATA,  required: true },
      { portId: 'reducer', label: '리듀서',  portType: PORT_TYPES.LOGIC, required: true },
    ],
    outputs: [
      { portId: 'out', label: '결과값', portType: PORT_TYPES.DATA },
    ],
    defaultProps: { accumName: 'acc', itemName: 'item', initial: 0, expression: 'acc + item' },
  },
};

/**
 * logic 노드 → freelang-light script 블록 변환
 * @param {object} node
 * @returns {string}
 */
function toFreelangCode(node) {
  const { logicType, props } = node;
  const itemName  = safeName(props.itemName  ?? 'item');
  const indexName = safeName(props.indexName ?? 'i');
  const accumName = safeName(props.accumName ?? 'acc');
  const funcName  = safeName(props.name ?? 'myFunc');

  switch (logicType) {
    case 'if':
      return [
        `script {`,
        `  if (${props.condition}) {`,
        `    // then 연결 노드 실행`,
        `  } else {`,
        `    // else 연결 노드 실행`,
        `  }`,
        `}`,
      ].join('\n');

    case 'loop':
      return [
        `script {`,
        `  for (let ${indexName} = 0; ${indexName} < items.length; ${indexName}++) {`,
        `    let ${itemName} = items[${indexName}];`,
        `    // template 노드 렌더링`,
        `  }`,
        `}`,
      ].join('\n');

    case 'function':
      return [
        `script {`,
        `  function ${funcName}(${props.params.map(safeName).join(', ')}) {`,
        `    ${props.body}`,
        `  }`,
        `}`,
      ].join('\n');

    case 'map':
      return [
        `script {`,
        `  let result = array.map(function(${itemName}) {`,
        `    return ${props.expression};`,
        `  });`,
        `}`,
      ].join('\n');

    case 'filter':
      return [
        `script {`,
        `  let result = array.filter(function(${itemName}) {`,
        `    return ${props.condition};`,
        `  });`,
        `}`,
      ].join('\n');

    case 'reduce':
      return [
        `script {`,
        `  let result = array.reduce(function(${accumName}, ${itemName}) {`,
        `    return ${props.expression};`,
        `  }, ${props.initial});`,
        `}`,
      ].join('\n');

    default:
      return `script { /* ${logicType} */ }`;
  }
}

/**
 * FreeLang 식별자 검증 (코드 인젝션 방지)
 * @param {string} name
 * @returns {string}
 */
function safeName(name) {
  return String(name ?? 'var').replace(/[^\w]/g, '_');
}

module.exports = { LOGIC_TYPES, NODE_DEFS, createLogicNode, toFreelangCode, safeName };

