// FV-Lang WASM - C ABI (wasm-bindgen 없음)
// FreeLang mini-wasm-pack 호환

#[cfg(test)]
mod lexer_tests;

#[cfg(test)]
mod parser_tests;

#[cfg(test)]
mod type_checker_tests;

#[cfg(test)]
mod codegen_tests;

use std::alloc::{alloc as sys_alloc, dealloc as sys_dealloc, Layout};

// ── 메모리 관리 ──────────────────────────────
#[no_mangle]
pub extern "C" fn alloc(size: usize) -> *mut u8 {
    let layout = Layout::from_size_align(size, 1).unwrap();
    unsafe { sys_alloc(layout) }
}

#[no_mangle]
pub extern "C" fn dealloc(ptr: *mut u8, size: usize) {
    let layout = Layout::from_size_align(size, 1).unwrap();
    unsafe { sys_dealloc(ptr, layout) }
}

// ── 결과 직렬화 헬퍼 ─────────────────────────
// 반환 형식: [4바이트 길이(LE)] + [JSON 바이트]
// JS는 읽은 뒤 dealloc(ptr, 4 + len) 호출 필요
fn write_result(s: &str) -> *mut u8 {
    let bytes = s.as_bytes();
    let len = bytes.len();
    let total = 4 + len;
    // size=0 레이아웃은 UB이므로 최소 1 보장
    let alloc_size = total.max(1);
    let layout = Layout::from_size_align(alloc_size, 1).unwrap();
    unsafe {
        let ptr = sys_alloc(layout);
        let len_bytes = (len as u32).to_le_bytes();
        ptr.copy_from(len_bytes.as_ptr(), 4);
        if len > 0 {
            ptr.add(4).copy_from(bytes.as_ptr(), len);
        }
        ptr
    }
}

// JS에서 dealloc 호출 시 필요한 size 계산
// dealloc(ptr, result_total_size(ptr)) 으로 호출
#[no_mangle]
pub extern "C" fn result_total_size(ptr: *const u8) -> usize {
    let len = unsafe {
        let mut b = [0u8; 4];
        std::ptr::copy_nonoverlapping(ptr, b.as_mut_ptr(), 4);
        u32::from_le_bytes(b) as usize
    };

