// Phase 2 — Parser 단위 테스트
// fv-lang Parser의 AST 생성 동작 검증

#[cfg(test)]
mod tests {
    use fv_lang::{Lexer, Parser};
    use fv_lang::ast::{Definition, Expression, Literal, Statement};

    // ── 헬퍼 ──────────────────────────────────────

    /// 소스 코드를 파싱해 Program 반환 (실패 시 패닉)
    fn parse(src: &str) -> fv_lang::ast::Program {
        let lex = Lexer::new(src).expect("Lexer::new 실패");
        let tokens = lex.tokenize().expect("tokenize 실패");
        let parser = Parser::new(tokens).expect("Parser::new 실패");
        parser.parse().expect("parse 실패")
    }

    /// get_ast_json 래퍼 - JSON 문자열 검증용
    fn ast_json(src: &str) -> String {
        crate::get_ast_json(src)
    }

    // ══════════════════════════════════════════════
    // 1. LetBinding 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_let_integer_literal() {
        // let x = 42; → LetBinding { name: "x", value: Literal(Integer(42)) }
        let prog = parse("let x = 42;");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "x");
                match value.as_ref() {
                    Expression::Literal(Literal::Integer(n)) => assert_eq!(*n, 42),
                    other => panic!("Integer 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_float_literal() {
        // let pi = 3.14;
        let prog = parse("let pi = 3.14;");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "pi");
                match value.as_ref() {
                    Expression::Literal(Literal::Float(f)) => {
                        let diff = (f - 3.14_f64).abs();
                        assert!(diff < 1e-9, "3.14 기대, 실제: {}", f);
                    }
                    other => panic!("Float 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_string_literal() {
        // let greeting = "hello";
        let prog = parse(r#"let greeting = "hello";"#);
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "greeting");
                match value.as_ref() {
                    Expression::Literal(Literal::String(s)) => assert_eq!(s, "hello"),
                    other => panic!("String 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_bool_true() {
        // let flag = true;
        let prog = parse("let flag = true;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "flag");
                match value.as_ref() {
                    Expression::Literal(Literal::Boolean(b)) => assert!(*b),
                    other => panic!("Boolean true 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_bool_false() {
        // let done = false;
        let prog = parse("let done = false;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "done");
                match value.as_ref() {
                    Expression::Literal(Literal::Boolean(b)) => assert!(!b),
                    other => panic!("Boolean false 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_variable_reference() {
        // let y = x; (변수 참조)
        let prog = parse("let y = x;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "y");
                match value.as_ref() {
                    Expression::Variable(var) => assert_eq!(var, "x"),
                    other => panic!("Variable 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 2. BinaryOp 산술 연산 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_binary_add() {
        // let r = 1 + 2;
        let prog = parse("let r = 1 + 2;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => {
                match value.as_ref() {
                    Expression::BinaryOp { op, left, right } => {
                        assert!(op.contains("Plus"), "op에 'Plus' 포함 기대: {}", op);
                        assert!(matches!(left.as_ref(), Expression::Literal(Literal::Integer(1))),
                            "left가 Integer(1) 기대");
                        assert!(matches!(right.as_ref(), Expression::Literal(Literal::Integer(2))),
                            "right가 Integer(2) 기대");
                    }
                    other => panic!("BinaryOp 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_subtract() {
        // let r = 10 - 3;
        let prog = parse("let r = 10 - 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Minus"), "op에 'Minus' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_multiply() {
        // let r = 3 * 4;
        let prog = parse("let r = 3 * 4;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Star"), "op에 'Star' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_divide() {
        // let r = 10 / 2;
        let prog = parse("let r = 10 / 2;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Slash"), "op에 'Slash' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_modulo() {
        // let r = 7 % 3;
        let prog = parse("let r = 7 % 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Percent"), "op에 'Percent' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 3. BinaryOp 비교/논리 연산 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_binary_equality() {
        // let r = x == y;
        let prog = parse("let r = x == y;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Eq"), "op에 'Eq' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_less_than() {
        // let r = a < b;
        let prog = parse("let r = a < b;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Lt"), "op에 'Lt' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_logical_and() {
        // let r = a && b;
        let prog = parse("let r = a && b;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
