    // ══════════════════════════════════════════════
    // 5. 중첩 표현식 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_nested_arithmetic() {
        // let r = (1 + 2) * 3; — 파서는 괄호로 연산자 우선순위 재정의 허용
        let prog = parse("let r = (1 + 2) * 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => {
                // 최상위는 BinaryOp(Star) 이어야 함
                match value.as_ref() {
                    Expression::BinaryOp { op, left, .. } => {
                        assert!(op.contains("Star"), "최상위는 곱셈: {}", op);
                        // left는 1+2
                        match left.as_ref() {
                            Expression::BinaryOp { op: inner_op, .. } => {
                                assert!(inner_op.contains("Plus"), "내부는 덧셈: {}", inner_op);
                            }
                            other => panic!("내부 BinaryOp 기대, 실제: {:?}", other),
                        }
                    }
                    other => panic!("BinaryOp 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_operator_precedence_add_mul() {
        // 1 + 2 * 3 → BinaryOp(Plus, 1, BinaryOp(Star, 2, 3))
        // (곱셈이 덧셈보다 높은 우선순위)
        let prog = parse("let r = 1 + 2 * 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, right, .. } => {
                    assert!(op.contains("Plus"), "최상위는 덧셈: {}", op);
                    match right.as_ref() {
                        Expression::BinaryOp { op: rhs_op, .. } => {
                            assert!(rhs_op.contains("Star"), "우측은 곱셈: {}", rhs_op);
                        }
                        other => panic!("우측 BinaryOp(Star) 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 6. FunctionCall 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_function_call_no_args() {
        // let r = greet();
        let prog = parse("let r = greet();");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "greet");
                    assert!(args.is_empty(), "인자 없음 기대");
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_one_arg() {
        // let r = double(x);
        let prog = parse("let r = double(x);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "double");
                    assert_eq!(args.len(), 1);
                    match &args[0] {
                        Expression::Variable(v) => assert_eq!(v, "x"),
                        other => panic!("Variable 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_two_args() {
        // let r = add(1, 2);
        let prog = parse("let r = add(1, 2);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "add");
                    assert_eq!(args.len(), 2, "인자 2개 기대");
                    match &args[0] {
                        Expression::Literal(Literal::Integer(1)) => {}
                        other => panic!("첫 번째 인자 1 기대, 실제: {:?}", other),
                    }
                    match &args[1] {
                        Expression::Literal(Literal::Integer(2)) => {}
                        other => panic!("두 번째 인자 2 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_expression_arg() {
        // let r = square(a + b);
        let prog = parse("let r = square(a + b);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "square");
                    assert_eq!(args.len(), 1);
                    match &args[0] {
                        Expression::BinaryOp { op, .. } => {
                            assert!(op.contains("Plus"), "인자가 덧셈: {}", op);
                        }
                        other => panic!("BinaryOp 인자 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 7. IfExpr (표현식 형태) 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_if_expr_with_else() {
        // let r = if cond { 1 } else { 0 };
        let prog = parse("let r = if cond { 1 } else { 0 };");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::IfExpr { condition, then_expr, else_expr } => {
                    match condition.as_ref() {
                        Expression::Variable(v) => assert_eq!(v, "cond"),
                        other => panic!("조건 Variable 기대, 실제: {:?}", other),
                    }
                    match then_expr.as_ref() {
                        Expression::Literal(Literal::Integer(1)) => {}
                        other => panic!("then에 1 기대, 실제: {:?}", other),
                    }
                    assert!(else_expr.is_some(), "else 분기 있어야 함");
                    match else_expr.as_ref().unwrap().as_ref() {
                        Expression::Literal(Literal::Integer(0)) => {}
                        other => panic!("else에 0 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("IfExpr 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_if_expr_without_else() {
        // let r = if flag { 42 };
        let prog = parse("let r = if flag { 42 };");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::IfExpr { else_expr, .. } => {
                    assert!(else_expr.is_none(), "else 없어야 함");
                }
                other => panic!("IfExpr 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 8. If Statement 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_if_statement_with_else() {
        // if x { let a = 1; } else { let b = 2; }
        let prog = parse("if x { let a = 1; } else { let b = 2; }");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::If { condition, then_branch, else_branch } => {
                match condition.as_ref() {
                    Expression::Variable(v) => assert_eq!(v, "x"),
                    other => panic!("Variable 기대, 실제: {:?}", other),
                }
                assert_eq!(then_branch.len(), 1, "then 블록 1개 문장 기대");
                assert!(else_branch.is_some(), "else 분기 있어야 함");
                assert_eq!(else_branch.as_ref().unwrap().len(), 1, "else 블록 1개 문장 기대");
            }
            other => panic!("If Statement 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_if_statement_without_else() {
        // if done { let r = 0; }
        let prog = parse("if done { let r = 0; }");
        match &prog.statements[0] {
            Statement::If { else_branch, .. } => {
                assert!(else_branch.is_none(), "else 없어야 함");
            }
            other => panic!("If Statement 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 9. Function Definition 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_fn_definition_no_params() {
        // fn hello() -> Int { let r = 0; return r; }
        let prog = parse("fn hello() -> Int { let r = 0; return r; }");
        assert_eq!(prog.definitions.len(), 1);
        match &prog.definitions[0] {
            Definition::Function { name, params, body } => {
                assert_eq!(name, "hello");
                assert!(params.is_empty(), "파라미터 없음 기대");
                assert_eq!(body.len(), 2, "본문 2개 문장 기대");
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_fn_definition_one_param() {
        // fn double(x: Int) -> Int { return x; }
        let prog = parse("fn double(x: Int) -> Int { return x; }");
        match &prog.definitions[0] {
            Definition::Function { name, params, body } => {
                assert_eq!(name, "double");
                assert_eq!(params.len(), 1, "파라미터 1개 기대");
                assert_eq!(params[0], "x");
                assert_eq!(body.len(), 1);
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_fn_definition_two_params() {
        // fn add(a: Int, b: Int) -> Int { return a; }
        let prog = parse("fn add(a: Int, b: Int) -> Int { return a; }");
        match &prog.definitions[0] {
            Definition::Function { name, params, .. } => {
                assert_eq!(name, "add");
                assert_eq!(params.len(), 2, "파라미터 2개 기대");
                assert_eq!(params[0], "a");
                assert_eq!(params[1], "b");
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

