    // 11. 여러 구문 순서 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_multiple_let_statements() {
        let prog = parse("let a = 1;\nlet b = 2;\nlet c = 3;");
        assert_eq!(prog.statements.len(), 3, "3개 let 구문 기대");
        let names: Vec<&str> = prog.statements.iter().map(|s| {
            match s {
                Statement::LetBinding { name, .. } => name.as_str(),
                _ => panic!("LetBinding 기대"),
            }
        }).collect();
        assert_eq!(names, vec!["a", "b", "c"]);
    }

    #[test]
    fn test_fn_and_statements_separated() {
        // 함수 정의 + 최상위 구문이 분리됨
        let prog = parse("fn greet() -> Int { return 1; }\nlet x = 42;");
        assert_eq!(prog.definitions.len(), 1, "함수 1개 기대");
        assert_eq!(prog.statements.len(), 1, "최상위 구문 1개 기대");
    }

