/**
 * FV-Lang WASM C ABI → ES Module 래퍼
 * C ABI exports를 친화적인 JS 함수로 변환
 *
 * 메모리 프로토콜:
 *   - writeStr(str)  → WASM 메모리에 UTF-8 문자열 기록, [ptr, len] 반환
 *   - readResult(ptr)→ [4-byte LE 길이][JSON 바이트] 읽고 JSON 파싱 후 dealloc
 *   - readCStr(ptr)  → null 종료 문자열 읽기
 */

'use strict';

const _enc = new TextEncoder();
const _dec = new TextDecoder();
let _wasm = null;

// ─── 메모리 헬퍼 ────────────────────────────────────────────────

function _writeStr(str) {
  const bytes = _enc.encode(str);
  const ptr   = _wasm.alloc(bytes.length || 1);
  new Uint8Array(_wasm.memory.buffer, ptr, bytes.length).set(bytes);
  return [ptr, bytes.length];
}

function _readResult(ptr) {
  const mem = new Uint8Array(_wasm.memory.buffer);
  const len = mem[ptr] | (mem[ptr+1]<<8) | (mem[ptr+2]<<16) | (mem[ptr+3]<<24);
  const json = _dec.decode(mem.slice(ptr + 4, ptr + 4 + len));
  _wasm.dealloc(ptr, 4 + len);
  try { return JSON.parse(json); } catch { return { success: false, error: 'JSON 파싱 실패: ' + json }; }
}

function _readCStr(ptr) {
  const mem = new Uint8Array(_wasm.memory.buffer);
  let end = ptr;
  while (mem[end] !== 0 && end < ptr + 256) end++;
  return _dec.decode(mem.slice(ptr, end));
}

// ─── 공개 API ──────────────────────────────────────────────────

/**
 * WASM 모듈 초기화
 * @param {string|URL} [wasmPath] - .wasm 파일 경로 (기본: ./fv_lang_wasm.wasm)
 */
export async function init(wasmPath) {
  const url = wasmPath || new URL('./fv_lang_wasm.wasm', import.meta.url).href;

  const instantiate = async (buf) => {
    const result = await WebAssembly.instantiate(buf, {});
    _wasm = result.instance.exports;
  };

  // fetch + instantiateStreaming 시도, 실패 시 fallback
  try {
    const resp = await fetch(url);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const buf = await resp.arrayBuffer();
    await instantiate(buf);
  } catch (e) {
    throw new Error('WASM 로드 실패: ' + e.message);
  }

  return _wasm;
}

/**
 * FV-Lang 코드 실행
 * @param {string} code
 * @returns {{ success: boolean, output?: string, error?: string }}
 */
export function eval_fv(code) {
  if (!_wasm) throw new Error('WASM 미초기화. init() 먼저 호출 필요');
  const [ptr, len] = _writeStr(code);
  const resultPtr  = _wasm.eval_fv_raw(ptr, len);
  _wasm.dealloc(ptr, len || 1);
  return _readResult(resultPtr);
}

/**
 * FV-Lang 코드를 AST JSON으로 파싱
 * @param {string} code
 * @returns {{ success: boolean, ast?: object, error?: string }}
 */
export function parse_to_ast(code) {
  if (!_wasm) throw new Error('WASM 미초기화. init() 먼저 호출 필요');
  const [ptr, len] = _writeStr(code);
  const resultPtr  = _wasm.parse_to_ast_raw(ptr, len);
  _wasm.dealloc(ptr, len || 1);
  return _readResult(resultPtr);
}

/**
 * FV-Lang 버전 문자열 반환
 * @returns {string}
 */
export function fv_version() {
  if (!_wasm) return 'FV-Lang (WASM 미로드)';
  return _readCStr(_wasm.fv_version_raw());
}

/**
 * FV-Lang 소스 → 토큰 배열 JSON
 * @param {string} code
 * @returns {{ success: boolean, tokens?: string[], error?: string }}
 */
export function get_tokens(code) {
  if (!_wasm) throw new Error('WASM 미초기화. init() 먼저 호출 필요');
  const [ptr, len] = _writeStr(code);
  const resultPtr  = _wasm.get_tokens_raw(ptr, len);
  _wasm.dealloc(ptr, len || 1);
  return _readResult(resultPtr);
}

