    this.id      = id;
    this.roomId  = null;
    this.alive   = true;
    this.buf     = Buffer.alloc(0);
  }

  send(obj) {
    try {
      const json  = JSON.stringify(obj);
      const frame = encodeFrame(json);
      this.socket.write(frame);
    } catch { /* 소켓 닫힘 */ }
  }

  close(code = 1000, reason = '') {
    try {
      const buf = Buffer.alloc(2 + reason.length);
      buf.writeUInt16BE(code, 0);
      buf.write(reason, 2);
      this.socket.write(encodeFrame(buf, OP_CLOSE));
      this.socket.end();
    } catch { this.socket.destroy(); }
  }
}

// ─── WebSocket 핸드쉐이크 ────────────────────────────────────

const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';

function doHandshake(req, socket) {
  const key = req.headers['sec-websocket-key'];
  if (!key) { socket.destroy(); return false; }

  const crypto = require('crypto');
  const accept = crypto.createHash('sha1')
    .update(key + GUID)
    .digest('base64');

  socket.write(
    'HTTP/1.1 101 Switching Protocols\r\n' +
    'Upgrade: websocket\r\n' +
    'Connection: Upgrade\r\n' +
    `Sec-WebSocket-Accept: ${accept}\r\n` +
    '\r\n'
  );
  return true;
}

// ─── 프레임 인코딩 ────────────────────────────────────────────

function encodeFrame(data, opcode = OP_TEXT) {
  const payload = typeof data === 'string' ? Buffer.from(data, 'utf8') : data;
  const len     = payload.length;

  let header;
  if (len < 126) {
    header = Buffer.alloc(2);
    header[0] = 0x80 | opcode;
    header[1] = len;
  } else if (len < 65536) {
    header = Buffer.alloc(4);
    header[0] = 0x80 | opcode;
    header[1] = 126;
    header.writeUInt16BE(len, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = 0x80 | opcode;
    header[1] = 127;
    header.writeBigUInt64BE(BigInt(len), 2);
  }
  return Buffer.concat([header, payload]);
}

// ─── 프레임 디코딩 ────────────────────────────────────────────

function decodeFrame(buf) {
  if (buf.length < 2) return null;

  const fin    = (buf[0] & 0x80) !== 0;
  const opcode = buf[0] & 0x0F;
  const masked = (buf[1] & 0x80) !== 0;
  let   payLen = buf[1] & 0x7F;
  let   offset = 2;

  if (payLen === 126) {
    if (buf.length < 4) return null;
    payLen = buf.readUInt16BE(2);
    offset = 4;
  } else if (payLen === 127) {
    if (buf.length < 10) return null;
    payLen = Number(buf.readBigUInt64BE(2));
    offset = 10;
  }

  if (masked) offset += 4;
  if (buf.length < offset + payLen) return null;

  const maskKey = masked ? buf.slice(offset - 4, offset) : null;
  const payload = Buffer.from(buf.slice(offset, offset + payLen));

  if (masked && maskKey) {
    for (let i = 0; i < payload.length; i++) {
      payload[i] ^= maskKey[i % 4];
    }
  }

  return { fin, opcode, payload, consumed: offset + payLen };
}

// ─── 룸 관리 ──────────────────────────────────────────────────

function getOrCreateRoom(roomId) {
  if (!rooms.has(roomId)) {
    if (rooms.size >= MAX_ROOMS) {
      // 가장 오래된 빈 룸 제거
      for (const [id, room] of rooms) {
        if (room.clients.size === 0) { rooms.delete(id); break; }
      }
    }
    rooms.set(roomId, {
      clients:   new Map(),
      graph:     { nodes: [], edges: [], id: roomId },
      createdAt: Date.now(),
    });
  }
  return rooms.get(roomId);
}

function broadcast(roomId, msg, excludeId = null) {
  const room = rooms.get(roomId);
  if (!room) return;
  for (const [id, client] of room.clients) {
    if (id !== excludeId) client.send(msg);
  }
}

function getRoomInfo(roomId) {
  const room = rooms.get(roomId);
  if (!room) return null;
  return {
    roomId,
    clientCount: room.clients.size,
    clients:     [...room.clients.keys()],
    graph:       room.graph,
  };
}

// ─── 메시지 핸들러 ────────────────────────────────────────────

function handleMessage(client, raw) {
  let msg;
  try { msg = JSON.parse(raw); }
  catch { return client.send({ type: 'error', error: '잘못된 JSON' }); }

  const { type, roomId, payload } = msg;

  switch (type) {
    case 'join': {
      if (!roomId) return client.send({ type: 'error', error: 'roomId 필수' });
      const room = getOrCreateRoom(roomId);
      if (room.clients.size >= MAX_CLIENTS_PER_ROOM) {
        return client.send({ type: 'error', error: '룸 최대 인원 초과' });
      }
      // 이전 룸에서 퇴장
      if (client.roomId) leaveRoom(client);

      client.roomId = roomId;
      room.clients.set(client.id, client);

      // 입장 확인 + 현재 그래프 상태 전송
      client.send({ type: 'joined', roomId, graph: room.graph, clientId: client.id });
      // 다른 클라이언트에게 알림
      broadcast(roomId, { type: 'peer_joined', roomId, clientId: client.id, clientCount: room.clients.size }, client.id);
      break;
    }

    case 'leave':
      leaveRoom(client);
      break;

    case 'graph_update': {
      const room = rooms.get(client.roomId);
      if (!room) return client.send({ type: 'error', error: '룸 없음' });
      if (payload?.graph) room.graph = payload.graph;
      broadcast(client.roomId, { type: 'graph_update', roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
      break;
    }

    case 'node_add':
    case 'node_remove':
    case 'node_move':
    case 'edge_add':
    case 'edge_remove': {
      const room = rooms.get(client.roomId);
      if (!room) return client.send({ type: 'error', error: '룸 없음' });
      // 그래프 상태 업데이트
      _applyOp(room.graph, type, payload);
      broadcast(client.roomId, { type, roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
      break;
    }

    case 'cursor_move':
      // 커서 이동은 저장 없이 브로드캐스트만
      broadcast(client.roomId, { type: 'cursor_move', roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
      break;

    case 'ping':
      client.send({ type: 'pong', ts: Date.now() });
      break;

    case 'room_info':
      client.send({ type: 'room_info', data: getRoomInfo(client.roomId) });
      break;

    default:
      client.send({ type: 'error', error: `알 수 없는 타입: ${type}` });
  }
}

function _applyOp(graph, type, payload) {
  if (!payload) return;
  switch (type) {
    case 'node_add':
      if (payload.node) graph.nodes.push(payload.node);
      break;
    case 'node_remove':
      if (payload.nodeId) {
        graph.nodes = graph.nodes.filter(n => n.id !== payload.nodeId);
        graph.edges = graph.edges.filter(e => e.fn !== payload.nodeId && e.tn !== payload.nodeId);
      }
      break;
    case 'node_move':
      if (payload.nodeId) {
        const n = graph.nodes.find(n => n.id === payload.nodeId);
        if (n && payload.position) n.position = payload.position;
      }
      break;
    case 'edge_add':
      if (payload.edge) graph.edges.push(payload.edge);
      break;
    case 'edge_remove':
      if (payload.edgeId) graph.edges = graph.edges.filter((_, i) => i !== payload.edgeId);
      break;
  }
}

function leaveRoom(client) {
  if (!client.roomId) return;
  const room = rooms.get(client.roomId);
  if (room) {
    room.clients.delete(client.id);
    broadcast(client.roomId, { type: 'peer_left', roomId: client.roomId, clientId: client.id, clientCount: room.clients.size });
    // 빈 룸 정리 (10분 후)
    if (room.clients.size === 0) {
      setTimeout(() => {
        const r = rooms.get(client.roomId);
        if (r && r.clients.size === 0) rooms.delete(client.roomId);
      }, 600_000);
    }
  }
  client.roomId = null;
}

// ─── 서버 생성 ────────────────────────────────────────────────

let _clientIdCtr = 0;

function createWsServer() {
  const server = http.createServer((req, res) => {
    // HTTP REST 엔드포인트
    if (req.url === '/ws/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ok', rooms: rooms.size, clients: clients.size }));
      return;
    }
    if (req.url === '/ws/rooms') {
      const list = [...rooms.entries()].map(([id, r]) => ({
        roomId: id, clientCount: r.clients.size, createdAt: r.createdAt,
      }));
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ rooms: list }));
      return;
    }
    res.writeHead(426, { 'Content-Type': 'text/plain' });
    res.end('WebSocket Upgrade Required');
  });

  server.on('upgrade', (req, socket, head) => {
    if (!doHandshake(req, socket)) return;

    const clientId = `c${++_clientIdCtr}-${Date.now()}`;
    const client   = new WsClient(socket, clientId);
    clients.set(socket, client);

    socket.on('data', (chunk) => {
      client.buf = Buffer.concat([client.buf, chunk]);
      if (client.buf.length > MAX_MSG_BYTES) {
        client.close(1009, '메시지 너무 큼');
        return;
      }

      while (client.buf.length > 0) {
        const frame = decodeFrame(client.buf);
        if (!frame) break;
        client.buf = client.buf.slice(frame.consumed);

        switch (frame.opcode) {
          case OP_TEXT:
            client.alive = true;
            handleMessage(client, frame.payload.toString('utf8'));
            break;
          case OP_PING:
            socket.write(encodeFrame(frame.payload, OP_PONG));
            break;
          case OP_CLOSE:
            leaveRoom(client);
            clients.delete(socket);
            socket.end();
            break;
        }
      }
    });

    socket.on('close', () => {
      leaveRoom(client);
      clients.delete(socket);
    });

    socket.on('error', () => {
      leaveRoom(client);
      clients.delete(socket);
    });

    // 연결 확인 메시지
    client.send({ type: 'connected', clientId, ts: Date.now() });
  });

  // Ping/Pong 유지
  const pingTimer = setInterval(() => {
    for (const [sock, client] of clients) {
      if (!client.alive) { sock.destroy(); continue; }
      client.alive = false;
      try { sock.write(encodeFrame(Buffer.alloc(0), OP_PING)); }
      catch { sock.destroy(); }
    }
  }, PING_INTERVAL);

  server.on('close', () => clearInterval(pingTimer));

  return server;
}

// ─── 공개 API ────────────────────────────────────────────────

const wsServer = createWsServer();

if (require.main === module) {
  wsServer.listen(WS_PORT, () => {
    console.log(`\n🔌 FreeWire WebSocket 서버 시작`);
    console.log(`   ws://localhost:${WS_PORT}`);
    console.log(`   GET http://localhost:${WS_PORT}/ws/health`);
    console.log(`   GET http://localhost:${WS_PORT}/ws/rooms\n`);
  });
}

module.exports = { wsServer, rooms, clients, broadcast, getRoomInfo };

