/**
 * FreeWire Phase 12 — WebSocket 실시간 협업 서버 테스트
 * ws-server.js의 전체 파이프라인 검증
 */

'use strict';

const net  = require('net');
const http = require('http');
const path = require('path');
const { wsServer, rooms, broadcast, getRoomInfo } = require(path.join(__dirname, '../api/ws-server'));

// ─── 테스트 러너 ───────────────────────────────────────────────

let passed = 0, failed = 0;
const errors = [];

function test(name, fn) {
  try {
    fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    errors.push({ name, error: e.message });
    failed++;
  }
}

async function testAsync(name, fn) {
  try {
    await fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    errors.push({ name, error: e.message });
    failed++;
  }
}

function assert(cond, msg) { if (!cond) throw new Error(msg || '조건 실패'); }
function assertEqual(a, b, msg) { if (a !== b) throw new Error(msg || `${JSON.stringify(a)} !== ${JSON.stringify(b)}`); }
function assertIncludes(str, sub, msg) { if (!String(str).includes(sub)) throw new Error(msg || `"${sub}" not in "${String(str).slice(0,80)}"`); }

// ─── WebSocket 클라이언트 헬퍼 ────────────────────────────────

const WS_PORT = 14011; // 테스트용 포트

/** TCP 소켓으로 WebSocket 핸드쉐이크 수행 */
function wsConnect(port) {
  return new Promise((resolve, reject) => {
    const sock = net.createConnection(port, '127.0.0.1');
    const crypto = require('crypto');
    const key = crypto.randomBytes(16).toString('base64');
    const msgs = [];
    let buf = '';
    let upgraded = false;

    sock.once('connect', () => {
      sock.write(
        `GET / HTTP/1.1\r\nHost: localhost\r\n` +
        `Upgrade: websocket\r\nConnection: Upgrade\r\n` +
        `Sec-WebSocket-Key: ${key}\r\nSec-WebSocket-Version: 13\r\n\r\n`
      );
    });

    sock.on('data', (chunk) => {
      if (!upgraded) {
        buf += chunk.toString();
        if (buf.includes('\r\n\r\n')) {
          upgraded = true;
          const rest = chunk.slice(chunk.indexOf('\r\n\r\n') + 4);
          if (rest.length > 0) processFrame(rest);
          resolve(api);
        }
        return;
      }
      processFrame(chunk);
    });

    function processFrame(buf) {
      if (buf.length < 2) return;
      const payLen = buf[1] & 0x7F;
      let offset = 2;
      let len = payLen;
      if (payLen === 126) { len = buf.readUInt16BE(2); offset = 4; }
      const payload = buf.slice(offset, offset + len);
      try {
        const msg = JSON.parse(payload.toString('utf8'));
        msgs.push(msg);
        if (api._listener) api._listener(msg);
      } catch {}
    }

    function sendMsg(obj) {
      const data  = JSON.stringify(obj);
      const bytes = Buffer.from(data, 'utf8');
      const mask  = crypto.randomBytes(4);
      const header = Buffer.alloc(bytes.length < 126 ? 6 : 8);
      header[0] = 0x81;
      header[1] = 0x80 | (bytes.length < 126 ? bytes.length : 126);
      if (bytes.length >= 126) header.writeUInt16BE(bytes.length, 2);
      const off = bytes.length < 126 ? 2 : 4;
      mask.copy(header, off);
      const payload = Buffer.from(bytes);
      for (let i = 0; i < payload.length; i++) payload[i] ^= mask[i % 4];
      sock.write(Buffer.concat([header.slice(0, off + 4), payload]));
    }

    function recv(timeout = 1000) {
      return new Promise((res, rej) => {
        if (msgs.length > 0) return res(msgs.shift());
        const timer = setTimeout(() => rej(new Error('recv timeout')), timeout);
        api._listener = (msg) => {
          clearTimeout(timer);
          api._listener = null;
          msgs.shift();
          res(msg);
        };
      });
    }

    const api = { send: sendMsg, recv, close: () => sock.destroy(), msgs, _listener: null };

    sock.on('error', reject);
  });
}

// ─── 서버 시작 ────────────────────────────────────────────────

async function main() {
  console.log('\n📦 Phase 12: WebSocket 실시간 협업 서버\n');

  await new Promise((res, rej) => wsServer.listen(WS_PORT, res).on('error', rej));

  // ── 1. 모듈 로드 ──────────────────────────────────────────
  console.log('1. 모듈 로드');
  test('wsServer 인스턴스 존재', () => assert(wsServer !== null));
  test('rooms Map 존재', () => assert(rooms instanceof Map));
  test('broadcast 함수 존재', () => assert(typeof broadcast === 'function'));
  test('getRoomInfo 함수 존재', () => assert(typeof getRoomInfo === 'function'));

  // ── 2. HTTP 엔드포인트 ────────────────────────────────────
  console.log('\n2. HTTP 엔드포인트');
  await testAsync('/ws/health 응답', async () => {
    const data = await httpGet(`http://127.0.0.1:${WS_PORT}/ws/health`);
    const json = JSON.parse(data);
    assertEqual(json.status, 'ok');
  });
  await testAsync('/ws/rooms 응답', async () => {
    const data = await httpGet(`http://127.0.0.1:${WS_PORT}/ws/rooms`);
    const json = JSON.parse(data);
    assert(Array.isArray(json.rooms));
  });

  // ── 3. WebSocket 연결 ─────────────────────────────────────
  console.log('\n3. WebSocket 연결');
  let ws1;
  await testAsync('핸드쉐이크 성공', async () => {
    ws1 = await wsConnect(WS_PORT);
    assert(ws1 !== null);
  });
  await testAsync('connected 메시지 수신', async () => {
    const msg = await ws1.recv();
    assertEqual(msg.type, 'connected');
    assert(typeof msg.clientId === 'string');
  });

  // ── 4. 룸 입장 ────────────────────────────────────────────
  console.log('\n4. 룸 입장');
  await testAsync('join 메시지 전송', async () => {
    ws1.send({ type: 'join', roomId: 'test-room-1' });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'joined');
    assertEqual(msg.roomId, 'test-room-1');
    assert(msg.graph !== undefined, 'graph 포함 기대');
  });
  test('rooms 맵에 룸 생성', () => {
    assert(rooms.has('test-room-1'), '룸 없음');
    assertEqual(rooms.get('test-room-1').clients.size, 1);
  });

  // ── 5. 두 번째 클라이언트 ─────────────────────────────────
  console.log('\n5. 멀티 클라이언트');
  let ws2;
  await testAsync('두 번째 클라이언트 연결', async () => {
    ws2 = await wsConnect(WS_PORT);
    await ws2.recv(); // connected
  });
  await testAsync('두 번째 클라이언트 룸 입장', async () => {
    ws2.send({ type: 'join', roomId: 'test-room-1' });
    const joinMsg = await ws2.recv(2000);
    assertEqual(joinMsg.type, 'joined');
  });
  await testAsync('peer_joined 브로드캐스트', async () => {
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'peer_joined');
    assertEqual(msg.roomId, 'test-room-1');
    assertEqual(msg.clientCount, 2);
  });
  test('룸에 2명 등록', () => {
    assertEqual(rooms.get('test-room-1').clients.size, 2);
  });

  // ── 6. 그래프 동기화 ─────────────────────────────────────
  console.log('\n6. 그래프 동기화');
  await testAsync('node_add 브로드캐스트', async () => {
    ws1.send({ type: 'node_add', roomId: 'test-room-1', payload: { node: { id: 'n1', type: 'component' } } });
    const msg = await ws2.recv(2000);
    assertEqual(msg.type, 'node_add');
    assertEqual(msg.payload.node.id, 'n1');
    assert(msg.from !== null, 'from 없음');
    assert(typeof msg.ts === 'number', 'ts 없음');
  });
  test('node_add 후 그래프 상태 반영', () => {
    const room = rooms.get('test-room-1');
    assert(room.graph.nodes.some(n => n.id === 'n1'), '노드 없음');
  });
  await testAsync('node_move 브로드캐스트', async () => {
    ws1.send({ type: 'node_move', roomId: 'test-room-1', payload: { nodeId: 'n1', position: { x: 100, y: 200 } } });
    const msg = await ws2.recv(2000);
    assertEqual(msg.type, 'node_move');
    assertEqual(msg.payload.nodeId, 'n1');
  });
  test('node_move 후 위치 반영', () => {
    const room = rooms.get('test-room-1');
    const node = room.graph.nodes.find(n => n.id === 'n1');
    assert(node && node.position?.x === 100, '위치 미반영');
  });
  await testAsync('edge_add 브로드캐스트', async () => {
    ws2.send({ type: 'edge_add', roomId: 'test-room-1', payload: { edge: { fn: 'n1', tn: 'n2', fp: 0, tp: 0 } } });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'edge_add');
  });
  await testAsync('node_remove 후 엣지도 제거', async () => {
    ws1.send({ type: 'node_remove', roomId: 'test-room-1', payload: { nodeId: 'n1' } });
    const msg = await ws2.recv(2000);
    assertEqual(msg.type, 'node_remove');
    const room = rooms.get('test-room-1');
    assert(!room.graph.nodes.some(n => n.id === 'n1'), '노드 미제거');
    assert(!room.graph.edges.some(e => e.fn === 'n1'), '엣지 미제거');
  });

  // ── 7. graph_update (전체 교체) ───────────────────────────
  console.log('\n7. graph_update');
  await testAsync('graph_update 전체 교체', async () => {
    const newGraph = { id: 'test-room-1', nodes: [{ id: 'x1' }], edges: [] };
    ws1.send({ type: 'graph_update', roomId: 'test-room-1', payload: { graph: newGraph } });
    const msg = await ws2.recv(2000);
    assertEqual(msg.type, 'graph_update');
    assert(msg.payload.graph.nodes[0].id === 'x1');
  });

  // ── 8. 커서 이동 ─────────────────────────────────────────
  console.log('\n8. 커서 이동');
  await testAsync('cursor_move 브로드캐스트', async () => {
    ws2.send({ type: 'cursor_move', roomId: 'test-room-1', payload: { x: 50, y: 80 } });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'cursor_move');
    assertEqual(msg.payload.x, 50);
  });

  // ── 9. ping/pong ─────────────────────────────────────────
  console.log('\n9. ping/pong');
  await testAsync('ping → pong 응답', async () => {
    ws1.send({ type: 'ping' });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'pong');
    assert(typeof msg.ts === 'number');
  });

  // ── 10. room_info ─────────────────────────────────────────
  console.log('\n10. room_info');
  await testAsync('room_info 반환', async () => {
    ws1.send({ type: 'room_info' });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'room_info');
    assert(msg.data !== null);
    assertEqual(msg.data.roomId, 'test-room-1');
    assertEqual(msg.data.clientCount, 2);
  });

  // ── 11. 오류 처리 ─────────────────────────────────────────
  console.log('\n11. 오류 처리');
  await testAsync('잘못된 JSON → error 응답', async () => {
    // 수동으로 잘못된 텍스트 프레임 전송은 어렵지만 type 없는 메시지 테스트
    ws1.send({ type: 'unknown_type' });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'error');
  });
  await testAsync('join 없이 node_add → error', async () => {
    const ws3 = await wsConnect(WS_PORT);
    await ws3.recv(); // connected
    ws3.send({ type: 'node_add', payload: { node: { id: 'orphan' } } });
    const msg = await ws3.recv(2000);
    assertEqual(msg.type, 'error');
    ws3.close();
  });

  // ── 12. 퇴장 ────────────────────────────────────────────
  console.log('\n12. 퇴장');
  await testAsync('leave 후 peer_left 브로드캐스트', async () => {
    ws2.send({ type: 'leave' });
    const msg = await ws1.recv(2000);
    assertEqual(msg.type, 'peer_left');
    assertEqual(msg.clientCount, 1);
  });
  test('leave 후 룸 인원 감소', () => {
    assertEqual(rooms.get('test-room-1').clients.size, 1);
  });

  // 정리
  ws1.close();
  ws2.close();

  // ── 결과 ────────────────────────────────────────────────
  console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
  if (errors.length > 0) {
    console.log('\n실패 목록:');
    errors.forEach(e => console.log(`  ❌ ${e.name}: ${e.error}`));
  }

  wsServer.close();
  process.exit(failed > 0 ? 1 : 0);
}

function httpGet(url) {
