/**
 * FreeWire Phase 12+ - AI 마케팅팀 대시보드 생성기
 *
 * FreeWire 노드 그래프 → 마케팅 분석 대시보드 자동 생성
 *
 * 흐름:
 *   team-log.csv 또는 metrics JSON
 *   → 노드 그래프 자동 구성
 *   → GraphCompiler → .free 코드
 *   → FreeExecutor   → HTML/CSS/JS
 *   → 완성 대시보드
 */

'use strict';

const path = require('path');
const { GraphCompiler } = require('../compiler/graph-compiler');
const { FreeExecutor }  = require('../api/free-executor');
const { BrowserExecutor } = require('../wasm/browser-executor');

const compiler    = new GraphCompiler();
const executor    = new FreeExecutor();
const browserExec = new BrowserExecutor();

// ─── 데이터 → 노드 그래프 변환 ─────────────────────────────────

/**
 * 마케팅 메트릭 → FreeWire 노드 그래프 생성
 * @param {object} metrics
 * @returns {object} FreeWire 그래프 JSON
 */
function buildDashboardGraph(metrics) {
  const {
    blogViews     = 0,
    socialEngagement = 0,
    communityComments = 0,
    contentCount  = 0,
    agents        = [],
    period        = '주간',
  } = metrics;

  const uid = () => `mkt-${Date.now()}-${Math.floor(Math.random() * 10000)}`;

  // 노드 정의
  const titleNode = {
    id: uid(), type: 'component', componentType: 'text',
    props: { content: `FreeLang 마케팅 대시보드 (${period})`, tag: 'h1', color: '#6366f1' },
    meta: { position: { x: 0, y: 0 } },
  };

  const blogCard = {
    id: uid(), type: 'component', componentType: 'card',
    props: { title: '블로그 조회수', content: `${blogViews.toLocaleString()} views`, variant: 'default' },
    meta: { position: { x: 0, y: 120 } },
  };

  const socialCard = {
    id: uid(), type: 'component', componentType: 'card',
    props: { title: '소셜 참여율', content: `${socialEngagement.toFixed(1)}%`, variant: socialEngagement >= 5 ? 'glass' : 'default' },
    meta: { position: { x: 220, y: 120 } },
  };

  const communityCard = {
    id: uid(), type: 'component', componentType: 'card',
    props: { title: '커뮤니티 댓글', content: `${communityComments}개`, variant: 'default' },
    meta: { position: { x: 440, y: 120 } },
  };

  const contentCard = {
    id: uid(), type: 'component', componentType: 'card',
    props: { title: '콘텐츠 생산', content: `${contentCount}편`, variant: contentCount >= 3 ? 'glass' : 'default' },
    meta: { position: { x: 660, y: 120 } },
  };

  // KPI 달성도 계산
  const kpiNodes = [];
  const kpis = [
    { label: '블로그 조회수',  current: blogViews,        target: 1000, unit: 'views' },
    { label: '소셜 참여율',    current: socialEngagement, target: 5,    unit: '%' },
    { label: '커뮤니티 댓글', current: communityComments, target: 5,    unit: '개/주' },
    { label: '콘텐츠 생산',   current: contentCount,      target: 3,    unit: '편/주' },
  ];

  kpis.forEach((kpi, i) => {
    const pct = Math.min(100, Math.round((kpi.current / kpi.target) * 100));
    kpiNodes.push({
      id: uid(), type: 'component', componentType: 'text',
      props: {
        content: `${kpi.label}: ${kpi.current}${kpi.unit} / 목표 ${kpi.target}${kpi.unit} (${pct}%)`,
        tag: 'p',
        color: pct >= 100 ? '#22c55e' : pct >= 70 ? '#f59e0b' : '#ef4444',
      },
      meta: { position: { x: 0, y: 300 + i * 40 } },
    });
  });

  // 에이전트 상태 노드
  const agentStatusNode = {
    id: uid(), type: 'component', componentType: 'card',
    props: {
      title: 'AI 마케팅팀 상태',
      content: agents.length > 0
        ? agents.map(a => `${a.name}: ${a.status}`).join(' | ')
        : 'CMO | Content Writer | Social | Community | Analytics',
      variant: 'glass',
    },
    meta: { position: { x: 0, y: 500 } },
  };

  // 컨테이너 조합
  const metricsContainer = {
    id: uid(), type: 'component', componentType: 'container',
    props: { direction: 'row', gap: '16px', padding: '16px' },
    meta: { position: { x: 0, y: 100 } },
  };

  const kpiContainer = {
    id: uid(), type: 'component', componentType: 'container',
    props: { direction: 'column', gap: '8px', padding: '16px' },
    meta: { position: { x: 0, y: 280 } },
  };

  const rootContainer = {
    id: uid(), type: 'component', componentType: 'container',
    props: { direction: 'column', gap: '24px', padding: '24px' },
    meta: { position: { x: 0, y: 0 } },
  };

  const nodes = [
    rootContainer, titleNode,
    metricsContainer, blogCard, socialCard, communityCard, contentCard,
    kpiContainer, ...kpiNodes,
    agentStatusNode,
  ];

  // 엣지: 컨테이너에 자식 연결
  const edges = [
    { fn: titleNode.id,       fp: 0, tn: rootContainer.id,    tp: 0 },
    { fn: metricsContainer.id,fp: 0, tn: rootContainer.id,    tp: 0 },
    { fn: kpiContainer.id,    fp: 0, tn: rootContainer.id,    tp: 0 },
    { fn: agentStatusNode.id, fp: 0, tn: rootContainer.id,    tp: 0 },
    { fn: blogCard.id,        fp: 0, tn: metricsContainer.id, tp: 0 },
    { fn: socialCard.id,      fp: 0, tn: metricsContainer.id, tp: 0 },
    { fn: communityCard.id,   fp: 0, tn: metricsContainer.id, tp: 0 },
    { fn: contentCard.id,     fp: 0, tn: metricsContainer.id, tp: 0 },
    ...kpiNodes.map(n => ({ fn: n.id, fp: 0, tn: kpiContainer.id, tp: 0 })),
  ];

  return {
    id: `marketing-dashboard-${Date.now()}`,
