/**
 * FreeWire Phase 13 - 마케팅 대시보드 생성기 테스트
 */

'use strict';

const path = require('path');
const { buildDashboardGraph, generateDashboard, parseTeamLog } =
  require(path.join(__dirname, '../marketing/dashboard-generator'));

let passed = 0, failed = 0;
const errors = [];

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); passed++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); errors.push({ name, error: e.message }); failed++; }
}
function assert(cond, msg) { if (!cond) throw new Error(msg || '조건 실패'); }
function assertEqual(a, b, msg) { if (a !== b) throw new Error(msg || `${JSON.stringify(a)} !== ${JSON.stringify(b)}`); }
function assertIncludes(s, sub, msg) { if (!String(s).includes(sub)) throw new Error(msg || `"${sub}" not in string`); }

console.log('\n📦 Phase 13: 마케팅 대시보드 생성기\n');

// ── 1. buildDashboardGraph ──────────────────────────────────────
console.log('1. buildDashboardGraph()');

const sampleMetrics = {
  blogViews: 850,
  socialEngagement: 4.2,
  communityComments: 3,
  contentCount: 2,
  period: '주간',
};

test('그래프 구조 반환', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.nodes && Array.isArray(g.nodes), 'nodes 배열 없음');
  assert(g.edges && Array.isArray(g.edges), 'edges 배열 없음');
  assert(g.id,    'id 없음');
});

test('노드 개수 충분', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.nodes.length >= 8, `노드 부족: ${g.nodes.length}`);
});

test('엣지 개수 충분', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.edges.length >= 4, `엣지 부족: ${g.edges.length}`);
});

test('메트릭 없이도 동작 (기본값)', () => {
  const g = buildDashboardGraph({});
  assert(g.nodes.length > 0);
});

test('period 레이블 포함', () => {
  const g = buildDashboardGraph({ period: '월간' });
  assertIncludes(g.label, '월간');
});

test('container 노드 포함', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.nodes.some(n => n.componentType === 'container'), 'container 없음');
});

test('card 노드 포함 (메트릭 카드)', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.nodes.some(n => n.componentType === 'card'), 'card 없음');
});

test('text 노드 포함 (KPI)', () => {
  const g = buildDashboardGraph(sampleMetrics);
  assert(g.nodes.some(n => n.componentType === 'text'), 'text 없음');
});

// ── 2. generateDashboard ─────────────────────────────────────
console.log('\n2. generateDashboard()');

const dashResult = generateDashboard(sampleMetrics);

test('결과 객체 반환', () => {
  assert(dashResult && typeof dashResult === 'object');
});

test('preview HTML 반환', () => {
  assert(typeof dashResult.preview === 'string' && dashResult.preview.length > 0);
});

test('preview DOCTYPE 포함', () => {
  assertIncludes(dashResult.preview, '<!DOCTYPE html>');
});

test('graph 포함', () => {
  assert(dashResult.graph && Array.isArray(dashResult.graph.nodes));
});

test('stats 포함', () => {
  assert(dashResult.stats && typeof dashResult.stats === 'object');
});

test('compiled .free 코드 포함', () => {
  assert(typeof dashResult.compiled === 'string' && dashResult.compiled.length > 0);
});

test('compiled 코드에 component 키워드', () => {
  assertIncludes(dashResult.compiled, 'component');
});

test('달성 메트릭으로 green 색상', () => {
  const highMetrics = { blogViews: 1200, socialEngagement: 6, communityComments: 7, contentCount: 4 };
  const r = generateDashboard(highMetrics);
  assertIncludes(r.compiled + r.preview, '22c55e', '100% 달성 시 초록색 없음');
});

test('미달 메트릭으로 red 색상', () => {
  const lowMetrics = { blogViews: 100, socialEngagement: 1, communityComments: 0, contentCount: 0 };
  const r = generateDashboard(lowMetrics);
  assertIncludes(r.compiled + r.preview, 'ef4444', '미달 시 빨간색 없음');
});

// ── 3. parseTeamLog ────────────────────────────────────────────
console.log('\n3. parseTeamLog()');

const sampleCsv = `
2026-03-18 09:00,Content Writer,블로그 작성,성공,1200 views
2026-03-18 11:00,Social Media,트위터 배포,성공,6.5% engagement
2026-03-18 14:00,Community Manager,GeekNews 댓글,성공,3 comments
2026-03-19 09:00,Content Writer,블로그 작성,성공,800 views
2026-03-19 10:00,Community Manager,Reddit 댓글,성공,2 comments
`.trim();

test('CSV 파싱 성공', () => {
  const m = parseTeamLog(sampleCsv);
  assert(m && typeof m === 'object');
});

test('blogViews 합산', () => {
  const m = parseTeamLog(sampleCsv);
  assertEqual(m.blogViews, 2000, `blogViews: ${m.blogViews}`);
});

test('socialEngagement 파싱', () => {
  const m = parseTeamLog(sampleCsv);
  assertEqual(m.socialEngagement, 6.5, `engagement: ${m.socialEngagement}`);
});

test('communityComments 합산', () => {
  const m = parseTeamLog(sampleCsv);
  assertEqual(m.communityComments, 5, `comments: ${m.communityComments}`);
});

test('agents 목록 추출', () => {
  const m = parseTeamLog(sampleCsv);
  assert(m.agents.length >= 3, `에이전트 수 부족: ${m.agents.length}`);
});

test('빈 CSV → 기본값', () => {
  const m = parseTeamLog('');
  assertEqual(m.blogViews, 0);
});

// ── 4. 전체 파이프라인 ─────────────────────────────────────────
console.log('\n4. 전체 파이프라인 (CSV → 대시보드)');

test('CSV → 메트릭 → 대시보드 HTML', () => {
  const metrics = parseTeamLog(sampleCsv);
  const result  = generateDashboard(metrics);
  assert(result.preview.includes('<!DOCTYPE html>'), 'DOCTYPE 없음');
  assert(result.preview.length > 500, '대시보드 너무 짧음');
});

test('에이전트 현황 대시보드에 포함', () => {
  const metrics = parseTeamLog(sampleCsv);
  const result  = generateDashboard(metrics);
  assertIncludes(result.compiled, 'AI 마케팅팀 상태');
});

// ── 결과 ──────────────────────────────────────────────────────
console.log(`\n결과: ${passed} passed, ${failed} failed / ${passed + failed} total`);
if (errors.length > 0) {
  console.log('\n실패 목록:');
  errors.forEach(e => console.log(`  ❌ ${e.name}: ${e.error}`));
}
process.exit(failed > 0 ? 1 : 0);

