const sampleCsv = `
2026-03-18 09:00,Content Writer,블로그 작성,성공,1200 views
2026-03-18 11:00,Social Media,트위터 배포,성공,6.5% engagement
2026-03-18 14:00,Community Manager,GeekNews 댓글,성공,3 comments
2026-03-19 09:00,Content Writer,블로그 작성,성공,800 views
2026-03-19 10:00,Community Manager,Reddit 댓글,성공,2 comments
`.trim();

test('CSV 파싱 성공', () => {
