  assert(result.preview.includes('<!DOCTYPE html>'), 'DOCTYPE 없음');
  assert(result.preview.length > 500, '대시보드 너무 짧음');
});

test('에이전트 현황 대시보드에 포함', () => {
  const metrics = parseTeamLog(sampleCsv);
  const result  = generateDashboard(metrics);
  assertIncludes(result.compiled, 'AI 마케팅팀 상태');
});

// ── 결과 ──────────────────────────────────────────────────────
